SubProceso Factorial(n Como Entero) Como Entero
  Si n <= 1 Entonces
    Retornar 1;
  FinSi
  Retornar n * Factorial(n - 1);
FinSubProceso

Proceso Principal
  Escribir Factorial(5);
FinProceso

SubProceso EsPar(n Como Entero) Como Logico
  Si n = 0 Entonces
    Retornar Verdadero;
  FinSi
  Retornar EsImpar(n - 1);
FinSubProceso

SubProceso EsImpar(n Como Entero) Como Logico
  Si n = 0 Entonces
    Retornar Falso;
  FinSi
  Retornar EsPar(n - 1);
FinSubProceso

Proceso Principal
  Escribir EsPar(10), " ", EsImpar(7);
FinProceso

SubProceso SinFin(n Como Entero) Como Entero
  Retornar SinFin(n + 1);
FinSubProceso

Proceso Principal
  Escribir SinFin(0);
FinProceso
